from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
F=Fig('arrow173');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def lines(rows,kind='lines'):
 s0=len(paras)
 for r in rows:paras.append(pair(*r))
 layout.append({'type':kind,'indices':list(range(s0,len(paras)))})
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def red(lang):
 s=F.start(100)+t(330,40,'2NO',16)+F.arrow(380,470,34)+t(540,40,'N₂ + O₂',16)+t(330,84,'2NO₂',16)+F.arrow(380,470,78)+t(540,84,'N₂ + 2O₂',16)
 return s+'</svg>'
def ox(lang):
 s=F.start(100)+t(330,40,'2CO + O₂',16)+F.arrow(390,480,34,'Pt/Pd')+t(560,40,'2CO₂',16)+t(330,84,'HC + O₂',16)+F.arrow(390,480,78,'Pt/Pd')+t(560,84,'CO₂ + H₂O',16)
 return s+'</svg>'
def conv(lang):
 s=F.start(250)+t(560,24,K(lang,'Oxidizing-reducing catalyst','تکسیدی–تخفیفی عمل انگیز','اکسیډایز–ارجاع کوونکی کتلست'),13)+t(600,46,K(lang,'Engine-out gases:','انجن سے نکلنے والی گیسیں:','له انجن وتونکي ګازونه:')+' NOₓ, HC, CO',12)
 s+='<rect x="330" y="100" width="220" height="60" rx="26" fill="#4dd0e1" stroke="#00838f" stroke-width="2" transform="rotate(-18 440 130)"/>'+line(560,92,640,64,10,'#80deea')+line(320,168,250,192,10,'#80deea')
 s+=F.arrow(650,600,60)+F.arrow(250,200,196)+t(640,170,K(lang,'3-way','تین راہی','درې لاري'),12)+t(640,186,K(lang,'catalytic converter','عمل انگیز کنورٹر','کتلستي بدلوونکی'),12)
 s+=t(150,214,'NOₓ, HC, CO',12)+t(150,230,'H₂O, CO₂, '+K(lang,'other gases','دوسری گیسیں','نور ګازونه'),12)+t(300,222,'} '+K(lang,'Acceptable levels','قابلِ قبول سطحیں','د منلو وړ کچې'),12)
 return s+'</svg>'

add('23.1.3 Automobile, Pollutants and the Catalytic Converter','23.1.3 گاڑیاں، آلودگیاں اور عمل انگیز کنورٹر','23.1.3 موټر، ککړوونکي او کتلستي بدلوونکی','heading')
add('The major pollutants, present in the exhaust gases emitted by automobiles, are carbon monoxide (CO), nitric oxide (NO) and the hydrocarbons (HCs). These gases disturb the composition of the clean air and thus cause air pollution. When present in considerable amount, they cause damage to human health and plants life.','گاڑیوں سے خارج ہونے والی دھوئیں کی گیسوں میں موجود بڑی آلودگیاں کاربن مونو آکسائیڈ (CO)، نائٹرک آکسائیڈ (NO) اور ہائیڈروکاربنز (HCs) ہیں۔ یہ گیسیں صاف ہوا کی ترکیب کو بگاڑتی ہیں اور یوں فضائی آلودگی پیدا کرتی ہیں۔ قابلِ ذکر مقدار میں ہونے پر یہ انسانی صحت اور پودوں کی زندگی کو نقصان پہنچاتی ہیں۔','د موټرو له خوا د خوشې شویو اګزاسټ ګازونو اصلي ککړوونکي کاربن مونو اکساید (CO)، نایټریک اکساید (NO) او هایدروکاربنونه (HCs) دي. دا ګازونه د پاکې هوا ترکیب ګډوډوي او په دې توګه د هوا ککړتیا رامنځته کوي. کله چې په د پام وړ اندازه وي، د انسان روغتیا او د بوټو ژوند ته زیان رسوي.')
add('Tidbit','مختصر معلومات','لنډ معلومات','heading')
add('A 3-way catalytic converter is a device used in the exhaust system of the engine of the vehicles to reduce emission of hydrocarbon (HCs), carbon monoxide (CO) and nitric oxide (NO)','تین راہی عمل انگیز کنورٹر گاڑیوں کے انجن کے اخراجی نظام میں استعمال ہونے والا آلہ ہے جو ہائیڈروکاربن (HCs)، کاربن مونو آکسائیڈ (CO) اور نائٹرک آکسائیڈ (NO) کا اخراج کم کرتا ہے','درې لاري کتلستي بدلوونکی د موټرو د انجن په اګزاسټ سیستم کې کارېدونکې وسیله ده چې د هایدروکاربن (HCs)، کاربن مونو اکساید (CO) او نایټریک اکساید (NO) اخراج کموي')
add('One way of reducing emissions is to remove the pollutants from the exhaust gases. In automobiles, this is accomplished with a three-way catalytic converter.','اخراج کم کرنے کا ایک طریقہ دھوئیں کی گیسوں سے آلودگیاں نکالنا ہے۔ گاڑیوں میں یہ تین راہی عمل انگیز کنورٹر سے کیا جاتا ہے۔','د اخراج د کمولو یوه لاره له اګزاسټ ګازونو څخه د ککړوونکو لرې کول دي. په موټرو کې دا د درې لاري کتلستي بدلوونکي په واسطه ترسره کېږي.')
add('It converts harmful gases in the engine exhaust to relatively harmless gases; nitrogen (N₂), carbon dioxide (CO₂) and water.','یہ انجن کے دھوئیں میں نقصان دہ گیسوں کو نسبتاً بے ضرر گیسوں؛ نائٹروجن (N₂)، کاربن ڈائی آکسائیڈ (CO₂) اور پانی میں بدلتا ہے۔','دا د انجن په اګزاسټ کې زیانمن ګازونه په نسبتاً بې ضرره ګازونو؛ نایټروجن (N₂)، کاربن ډای اکساید (CO₂) او اوبو بدلوي.')
add('Working: A 3-way catalytic converter makes use of two catalysts to convert harmful gases to harmless gases in two chambers in succession. They are:','طریقۂ کار: تین راہی عمل انگیز کنورٹر یکے بعد دیگرے دو خانوں میں نقصان دہ گیسوں کو بے ضرر گیسوں میں بدلنے کے لیے دو عمل انگیز استعمال کرتا ہے۔ وہ یہ ہیں:','کار: درې لاري کتلستي بدلوونکی په دوو پرله پسې خونو کې د زیانمنو ګازونو په بې ضرره ګازونو بدلولو لپاره دوه کتلستونه کاروي. هغه دا دي:')
add('i. Reduction catalyst: Reducing chamber is made up of platinum and rhodium. The exhaust gases are first sent over the reduction catalyst. It converts oxides of nitrogen (NOₓ) to nitrogen (N₂) and oxygen (O₂). The following reaction take place when the exhaust gases pass over the reduction catalyst.','i. تخفیفی عمل انگیز: تخفیفی خانہ پلاٹینم اور روڈیم سے بنا ہے۔ دھوئیں کی گیسیں پہلے تخفیفی عمل انگیز پر سے گزاری جاتی ہیں۔ یہ نائٹروجن کے آکسائیڈز (NOₓ) کو نائٹروجن (N₂) اور آکسیجن (O₂) میں بدلتا ہے۔ دھوئیں کی گیسیں تخفیفی عمل انگیز پر سے گزرنے پر درج ذیل تعامل ہوتا ہے۔','i. ارجاع کتلست: د ارجاع خونه له پلاټینم او روډیم جوړه ده. اګزاسټ ګازونه لومړی د ارجاع کتلست پر سر لېږل کېږي. دا د نایټروجن اکسایډونه (NOₓ) په نایټروجن (N₂) او اکسیجن (O₂) بدلوي. کله چې اګزاسټ ګازونه د ارجاع له کتلست تېرېږي، لاندې تعامل کېږي.','list')
visual('chem12-p173-reduction-catalyst',red)
add('Thus, the reduction catalyst removes oxides of nitrogen and convert to oxygen and nitrogen, the harmless gases.','یوں تخفیفی عمل انگیز نائٹروجن کے آکسائیڈز کو ہٹا کر بے ضرر گیسوں آکسیجن اور نائٹروجن میں بدل دیتا ہے۔','په دې توګه د ارجاع کتلست د نایټروجن اکسایډونه لرې کوي او په بې ضرره ګازونو اکسیجن او نایټروجن یې بدلوي.')
add('ii. Oxidation catalyst: The oxidation chamber is made up of platinum and palladium. The exhaust gases that are free of oxide of nitrogen (NOₓ) are then sent over the oxidation catalyst which converts carbon monoxide (CO) and hydrocarbon (HC) in the gases into carbon dioxide (CO₂) and water. The following reaction takes place when the exhaust gases pass over the oxidation catalyst','ii. تکسیدی عمل انگیز: تکسیدی خانہ پلاٹینم اور پیلیڈیم سے بنا ہے۔ نائٹروجن آکسائیڈ (NOₓ) سے پاک دھوئیں کی گیسیں پھر تکسیدی عمل انگیز پر سے گزاری جاتی ہیں جو گیسوں میں موجود کاربن مونو آکسائیڈ (CO) اور ہائیڈروکاربن (HC) کو کاربن ڈائی آکسائیڈ (CO₂) اور پانی میں بدلتا ہے۔ دھوئیں کی گیسیں تکسیدی عمل انگیز پر سے گزرنے پر درج ذیل تعامل ہوتا ہے','ii. د اکسیډېشن کتلست: د اکسیډېشن خونه له پلاټینم او پالاډیم جوړه ده. هغه اګزاسټ ګازونه چې له نایټروجن اکساید (NOₓ) پاک وي، بیا د اکسیډېشن کتلست پر سر لېږل کېږي چې په ګازونو کې کاربن مونو اکساید (CO) او هایدروکاربن (HC) په کاربن ډای اکساید (CO₂) او اوبو بدلوي. کله چې اګزاسټ ګازونه د اکسیډېشن له کتلست تېرېږي، لاندې تعامل کېږي','list')
visual('chem12-p173-oxidation-catalyst',ox)
add('(HC are hydrocarbon, may be methane, ethane, or other hydrocarbons) The gases that finally come out of the catalytic chamber are N₂, CO₂, and H₂O. 3-way catalytic converters are so named because they are capable of eliminating three pollutants-NOₓ, CO and HC.','(HC ہائیڈروکاربن ہیں، جو میتھین، ایتھین یا دوسرے ہائیڈروکاربن ہو سکتے ہیں) آخر میں عمل انگیز خانے سے نکلنے والی گیسیں N₂، CO₂ اور H₂O ہیں۔ تین راہی عمل انگیز کنورٹرز کا یہ نام اس لیے ہے کہ یہ تین آلودگیوں NOₓ، CO اور HC کو ختم کرنے کی صلاحیت رکھتے ہیں۔','(HC هایدروکاربنونه دي، کېدای شي میتان، ایتان یا نور هایدروکاربنونه وي) هغه ګازونه چې په پای کې له کتلستي خونې وځي N₂، CO₂ او H₂O دي. درې لاري کتلستي بدلوونکو ته ځکه دا نوم ورکړل شوی چې د درې ککړوونکو NOₓ، CO او HC د له منځه وړلو وړتیا لري.')
visual('chem12-figure23-2',conv)
add('Fig: 23.1: The three-way catalytic remover for HCs, NO and CO, from automobile exhaust.','شکل 23.1: گاڑیوں کے دھوئیں سے HCs، NO اور CO کو ہٹانے والا تین راہی عمل انگیز۔','شکل 23.1: د موټرو له اګزاسټ څخه د HCs، NO او CO لرې کوونکی درې لاري کتلست.')
add('23.1.4 Industrial Smog','23.1.4 صنعتی سموگ','23.1.4 صنعتي سموګ','heading')
add('The word smog is combination of smoke and fog. It produces a yellow-brown colour in the atmosphere near the ground level which results in poor visibility in the area. There are two major types of smog: ‘industrial smog’ and ‘photochemical smog’. Industrial smog forms in the areas with high water vapours. It is caused by the burning of coal, vehicular emission and industrial fumes. Smog contains carbon particles like smoke, sulphur dioxide (SO₂) and other compounds. Burning of fossil fuel produces SO₂ which is produced due to the presence of sulphur in the fossil fuel. SO₂ gradually reacts further to form sulphur trioxide SO₃. Then in the presence of water or water vapours, droplets of H₂SO₄ are formed as a result of this reaction.',
 'سموگ کا لفظ دھوئیں (سموک) اور دھند (فوگ) کا مرکب ہے۔ یہ زمینی سطح کے قریب فضا میں زرد بھورا رنگ پیدا کرتا ہے جس سے علاقے میں حدِ نگاہ کم ہو جاتی ہے۔ سموگ کی دو بڑی اقسام ہیں: ’صنعتی سموگ‘ اور ’فوٹو کیمیکل سموگ‘۔ صنعتی سموگ زیادہ آبی بخارات والے علاقوں میں بنتا ہے۔ یہ کوئلہ جلانے، گاڑیوں کے اخراج اور صنعتی دھوئیں سے پیدا ہوتا ہے۔ سموگ میں دھوئیں جیسے کاربن کے ذرات، سلفر ڈائی آکسائیڈ (SO₂) اور دوسرے مرکبات ہوتے ہیں۔ فوسل ایندھن کے جلنے سے SO₂ بنتی ہے جو فوسل ایندھن میں سلفر کی موجودگی کی وجہ سے ہے۔ SO₂ آہستہ آہستہ مزید تعامل کر کے سلفر ٹرائی آکسائیڈ SO₃ بناتی ہے۔ پھر پانی یا آبی بخارات کی موجودگی میں اس تعامل کے نتیجے میں H₂SO₄ کے قطرے بنتے ہیں۔',
 'د سموګ کلمه د لوګي (سموک) او لړې (فوګ) ترکیب دی. د ځمکې سطحې ته نږدې په اتموسفیر کې ژېړ نسواري رنګ رامنځته کوي چې په سیمه کې د لید د کمښت لامل کېږي. د سموګ دوه لوی ډولونه شته: ’صنعتي سموګ‘ او ’فوټوکیمیکل سموګ‘. صنعتي سموګ په هغو سیمو کې جوړېږي چې د اوبو لوړ بخارات ولري. د ډبرینو سکرو د سوځولو، د موټرو د اخراج او صنعتي لوګیو له امله رامنځته کېږي. سموګ د لوګي په څېر د کاربن ذرې، سلفر ډای اکساید (SO₂) او نور مرکبات لري. د فوسیلي سونګ سوځېدل SO₂ تولیدوي چې په فوسیلي سونګ کې د سلفر د شتون له امله دی. SO₂ ورو ورو نور تعامل کوي او سلفر ټرای اکساید SO₃ جوړوي. بیا د اوبو یا د اوبو د بخاراتو په شتون کې د دې تعامل په پایله کې د H₂SO₄ څاڅکي جوړېږي.')
visual('chem12-p173-so3-h2so4',lambda l:F.start(60)+t(330,36,'SO₃ + H₂O',16)+F.arrow(390,480,30)+t(560,36,'H₂SO₄',16)+'</svg>')
add('H₂SO₄ is corrosive to materials as building stones and the human respiratory tract. Another coal-burning power station pollutant is soot, (primarily particles of carbon) which gives smoke its persistent dark colour. The soot also plays its role in the industrial smog.','H₂SO₄ عمارتی پتھروں جیسے مادوں اور انسانی نظامِ تنفس کے لیے تباہ کن ہے۔ کوئلہ جلانے والے بجلی گھروں کی ایک اور آلودگی کالک (بنیادی طور پر کاربن کے ذرات) ہے جو دھوئیں کو اس کا مستقل گہرا رنگ دیتی ہے۔ کالک بھی صنعتی سموگ میں اپنا کردار ادا کرتی ہے۔','H₂SO₄ د ودانیو ډبرو په څېر موادو او د انسان تنفسي لارې ته خوړونکی دی. د ډبرینو سکرو سوځوونکو برېښنا کوټو بل ککړوونکی دوده (په اصل کې د کاربن ذرې) ده چې لوګي ته خپل دوامداره تیاره رنګ ورکوي. دوده هم په صنعتي سموګ کې خپل رول لوبوي.')
add('23.1.5 Photochemical Smog','23.1.5 فوٹو کیمیکل سموگ','23.1.5 فوټوکیمیکل سموګ','heading')
add('Photochemical smog forms when pollutants from automobile and industrial exhausts, such as nitrogen oxides and organic compounds react together in the presence of sunlight and produce ozone gas. (Which is one of the primary components of the photochemical smog).','فوٹو کیمیکل سموگ اس وقت بنتا ہے جب گاڑیوں اور صنعتی دھوئیں کی آلودگیاں، جیسے نائٹروجن آکسائیڈز اور نامیاتی مرکبات، دھوپ کی موجودگی میں آپس میں تعامل کر کے اوزون گیس بناتی ہیں۔ (جو فوٹو کیمیکل سموگ کے بنیادی اجزا میں سے ایک ہے)۔','فوټوکیمیکل سموګ هغه وخت جوړېږي چې د موټرو او صنعتي اګزاسټ ککړوونکي لکه نایټروجن اکسایډونه او عضوي مرکبات د لمر رڼا په شتون کې سره تعامل وکړي او اوزون ګاز تولید کړي. (چې د فوټوکیمیکل سموګ له اصلي برخو څخه دی).')
add('Nitrogen dioxide + hydrocarbon + sunlight = ozone','نائٹروجن ڈائی آکسائیڈ + ہائیڈروکاربن + دھوپ = اوزون','نایټروجن ډای اکساید + هایدروکاربن + د لمر رڼا = اوزون')
